package com.vandorlabs.neoforge.propulsion;
import com.google.gson.*;
import com.vandorlabs.persistence.RedstoneLightData;
import java.nio.file.*;
/** Actual Source four-click transitions; independent saved fields remain intact. */
public final class PropulsionControlChecks {
 public static void main(String[] args)throws Exception{int rows=0,states=0;try(var lines=Files.lines(Path.of(args[0]))){for(String line:(Iterable<String>)lines::iterator){var r=JsonParser.parseString(line).getAsJsonObject();var frames=r.getAsJsonArray("frames");boolean independent=r.get("profile").getAsInt()==4;for(int step=0;step<4;step++){var before=frames.get(step).getAsJsonArray();var after=frames.get(step+1).getAsJsonArray();int first=independent?before.size()-1:0;boolean guard=false;for(int i=first;i<before.size();i++)guard|=before.get(i).getAsJsonArray().get(2).getAsInt()>0;int mode=(before.get(first).getAsJsonArray().get(0).getAsInt()+1)%3;for(int i=0;i<before.size();i++){var c=before.get(i).getAsJsonArray();var expected=after.get(i).getAsJsonArray();var data=new RedstoneLightData(c.get(2).getAsInt(),c.get(2).getAsInt()>0,c.get(2).getAsInt()>0?15:0,c.get(3).getAsBoolean(),c.get(1).getAsInt(),c.get(6).getAsBoolean(),false,false,8,!independent,9);var next=guard||i<first?data:data.manual(mode);if(next.manualMode()!=expected.get(0).getAsInt()||next.particleLevel!=expected.get(1).getAsInt()||next.channel!=expected.get(2).getAsInt()||next.manualOn!=expected.get(3).getAsBoolean()||next.powered(0)!=expected.get(4).getAsBoolean()||next.particles(0)!=expected.get(5).getAsBoolean()||next.initialized!=expected.get(6).getAsBoolean())throw new AssertionError("Actual Source manual transition "+rows+"/"+step+"/"+i);states++;}}rows++;}}if(rows!=972)throw new AssertionError("Coverage");System.out.println("Native propulsion controls PASS rows="+rows+" memberTransitions="+states+" actualSource off/light/stream/channelGuard/bottomLeft/join");}
}
